Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='sourcehealth', at=datetime(2026, 10, 27, 0, 0, 0), actor='assistant', title="Every source's health is one register keyed by its SourceKey, and it is not a cache", body="Every source the box reads from (a mail account, a plugin and each of its links, a Google account's calendars, the Drive) records its results in one health register keyed by its SourceKey, in source-health.json beside the triage heartbeat. The register is a semilattice joined under a lock beside the file, so writers that run at once lose nothing. It is box-local and never pushed, but it is not cache tier: the start of a failure cannot be rebuilt by syncing again, and the failing card and todo are filed once per episode from that start. A connection reads its health only through Connection::sources.", rationale="One register replaced three that each source kept its own way, and a failure's start must survive a resync so that no card is filed twice.", supersedes=()))